        Colors[0] := '0077EE'; // Blue
        Colors[1] := '00DD00'; // Green
        Colors[2] := 'FFFF00'; // Yellow
        Colors[3] := 'FFFFFF'; // White
        Colors[4] := 'EE0000'; // Red
        Colors[5] := 'FF6600'; // Orange

        for i := 0 to 5 do begin
            ax[i] := cos(Pi / 3 * i);
            ay[i] := sin(Pi / 3 * i);
        end;
        az := 1 / 2;

        W := 0.5;
        include 'Figures\Scripts\Cube_Coordinates.inc';

        A := W * 1.3;
        B := A - W;
        D := W * 1.006978;

        A1 := ArcCos(-1/4);
        A2 := ArcCos(-7/8); // 2*(Pi-A1)

        for i := 0 to 5 do begin
           Cx[i] := Cx[i] * 1.3;
           Cy[i] := Cy[i] * 1.3;
           Cz[i] := Cz[i] * 1.3;
        end;
